You are working on orders-service. The other folders are other teams' repositories, checked out read-only for reference.

# orders-service

Order management service for Meridian Retail (team Checkout). It places, lists, reads and cancels customer orders and publishes `OrderPlaced` and `OrderCancelled` events.

## Commands
- `npm run build` compiles `src/` and `test/` to `dist/`.
- `npm test` builds and runs the unit tests with `node --test`.
- `npm run arch` runs the dependency-cruiser checks.
- `npm run typecheck` type-checks without emitting.

## Using `createApp`
`createApp(deps?)` in `src/main.ts` is the entry point for integration tests and the one the unit tests use. Keep it working.
It returns `{ handle(method, path, body), events }`; `handle` resolves to `{ status, body }` and never rejects.
All `deps` are optional: `orderRepository`, `eventPublisher`, `paymentGateway`, `clock`, `idGenerator`.

```ts
const app = createApp({ eventPublisher, clock, idGenerator, paymentGateway });
const res = await app.handle("POST", "/orders", { customerId, customerEmail, channel, currency, lines });
// 201 { id, status, placedAt, currency, totalCents, lines }; invalid input -> 400; unknown order -> 404
```
Routes: `POST /orders`, `GET /orders?customerId=`, `GET /orders/{id}`, `POST /orders/{id}/cancel`, `GET /health`.
import { asObject, FieldReader } from "./fieldReader.js";

export const CHANNELS = ["web", "store", "marketplace"] as const;
export type Channel = (typeof CHANNELS)[number];

/** The part of `OrderPlaced` that analytics-ingest relies on. Other fields are ignored. */
export interface OrderPlacedEvent {
  readonly orderId: string;
  readonly placedAt: Date;
  readonly channel: Channel;
  readonly currency: string;
  readonly lines: ReadonlyArray<{ readonly sku: string; readonly qty: number }>;
}

/** The part of `OrderCancelled` that analytics-ingest relies on. */
export interface OrderCancelledEvent {
  readonly orderId: string;
  readonly cancelledAt: Date;
}

/**
 * Validates an untrusted `OrderPlaced` event. Every problem is collected;
 * any problem throws `ContractViolationError` (missing or unknown `channel`, unparseable `placedAt`, ...).
 */
export function decodeOrderPlaced(raw: unknown): OrderPlacedEvent {
  const event = asObject("OrderPlaced", raw);
  const reader = new FieldReader(event);

  if (event.type !== "OrderPlaced") {
    reader.issues.push(`type: expected "OrderPlaced", got ${JSON.stringify(event.type)}`);
  }
  const orderId = reader.string("orderId");
  const placedAt = reader.isoInstant("placedAt");
  const channel = reader.oneOf("channel", CHANNELS);
  const currency = reader.currency("currency");

  const lines = reader.array("lines").map((rawLine, index) => {
    const line = reader.child(`lines[${index}]`, rawLine);
    const decoded = { sku: line.string("sku"), qty: line.positiveInteger("qty") };
    reader.adopt(line);
    return decoded;
  });

  reader.assertValid("OrderPlaced");
  return { orderId, placedAt, channel, currency, lines };
}

export function decodeOrderCancelled(raw: unknown): OrderCancelledEvent {
  const event = asObject("OrderCancelled", raw);
  const reader = new FieldReader(event);

  if (event.type !== "OrderCancelled") {
    reader.issues.push(`type: expected "OrderCancelled", got ${JSON.stringify(event.type)}`);
  }
  const orderId = reader.string("orderId");
  const cancelledAt = reader.isoInstant("cancelledAt");

  reader.assertValid("OrderCancelled");
  return { orderId, cancelledAt };
}
import { ContractViolationError } from "./errors.js";
import { isCurrencyCode, isMinorUnits } from "./money.js";

/** The part of `OrderPlaced` that billing-service relies on. Other fields are ignored. */
export interface OrderPlacedEvent {
  readonly orderId: string;
  readonly customerId: string;
  readonly customerEmail: string;
  /** Integer, minor units (cents). */
  readonly totalCents: number;
  /** ISO-4217 code. */
  readonly currency: string;
}

const CONTRACT = "OrderPlaced";

/**
 * Validates an untrusted event and returns the fields billing needs.
 * Every problem is reported at once; any problem throws `ContractViolationError`.
 */
export function decodeOrderPlaced(raw: unknown): OrderPlacedEvent {
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    throw new ContractViolationError(CONTRACT, ["event must be a JSON object"]);
  }
  const event = raw as Record<string, unknown>;
  const issues: string[] = [];

  if (event.type !== "OrderPlaced") {
    issues.push(`type: expected "OrderPlaced", got ${describe(event.type)}`);
  }
  const orderId = requireString(event, "orderId", issues);
  const customerId = requireString(event, "customerId", issues);
  const customerEmail = requireString(event, "customerEmail", issues);
  if (customerEmail !== "" && !customerEmail.includes("@")) {
    issues.push("customerEmail: expected an email address");
  }

  const totalCents = event.totalCents;
  if (!isMinorUnits(totalCents)) {
    issues.push(`totalCents: expected an integer number of cents, got ${describe(totalCents)}`);
  }
  const currency = event.currency;
  if (!isCurrencyCode(currency)) {
    issues.push(`currency: expected an ISO-4217 code, got ${describe(currency)}`);
  }

  if (issues.length > 0 || !isMinorUnits(totalCents) || !isCurrencyCode(currency)) {
    throw new ContractViolationError(CONTRACT, issues);
  }
  return { orderId, customerId, customerEmail, totalCents, currency };
}

function requireString(event: Record<string, unknown>, key: string, issues: string[]): string {
  const value = event[key];
  if (typeof value !== "string" || value.trim() === "") {
    issues.push(`${key}: expected a non-empty string, got ${describe(value)}`);
    return "";
  }
  return value;
}

function describe(value: unknown): string {
  if (value === undefined) {
    return "missing";
  }
  if (value === null) {
    return "null";
  }
  return `${typeof value} ${JSON.stringify(value)}`;
}
import { utcDate } from "./core/dates.js";
import { ContractViolationError } from "./core/errors.js";
import {
  decodeOrderCancelled,
  decodeOrderPlaced,
  type OrderCancelledEvent,
  type OrderPlacedEvent,
} from "./core/events.js";
import type { DataLake } from "./core/ports.js";
import type { CancellationRow, OrderLineRow, OrderRow } from "./core/rows.js";

/** `OrderPlaced` -> row of table `orders`. */
export function toOrderRow(event: OrderPlacedEvent): OrderRow {
  return {
    order_id: event.orderId,
    placed_date: utcDate(event.placedAt),
    channel: event.channel,
    currency: event.currency,
    units: event.lines.reduce((total, line) => total + line.qty, 0),
  };
}

/** `OrderPlaced` -> rows of table `order_lines`; lines that repeat a SKU are summed. */
export function toLineRows(event: OrderPlacedEvent): OrderLineRow[] {
  const unitsBySku = new Map<string, number>();
  for (const line of event.lines) {
    unitsBySku.set(line.sku, (unitsBySku.get(line.sku) ?? 0) + line.qty);
  }
  return [...unitsBySku].map(([sku, units]) => ({ order_id: event.orderId, sku, units }));
}

/** `OrderCancelled` -> row of table `order_cancellations`. */
export function toCancellationRow(event: OrderCancelledEvent): CancellationRow {
  return { order_id: event.orderId, cancelled_date: utcDate(event.cancelledAt) };
}

/** Validates and ingests one `OrderPlaced` event. Rejects, writing nothing, when the event breaks the contract. */
export async function ingestOrderPlaced(lake: DataLake, raw: unknown): Promise<OrderRow> {
  const event = decodeOrderPlaced(raw);
  const row = toOrderRow(event);
  await lake.upsertOrder(row, toLineRows(event));
  return row;
}

/** Validates and ingests one `OrderCancelled` event. */
export async function ingestOrderCancelled(lake: DataLake, raw: unknown): Promise<CancellationRow> {
  const row = toCancellationRow(decodeOrderCancelled(raw));
  await lake.upsertCancellation(row);
  return row;
}

export type IngestResult =
  | { readonly kind: "OrderPlaced"; readonly row: OrderRow }
  | { readonly kind: "OrderCancelled"; readonly row: CancellationRow };

/** Routes an event by its `type` field. Unknown types are rejected rather than dropped silently. */
export async function ingestEvent(lake: DataLake, raw: unknown): Promise<IngestResult> {
  const type = typeof raw === "object" && raw !== null ? (raw as { type?: unknown }).type : undefined;
  switch (type) {
    case "OrderPlaced":
      return { kind: "OrderPlaced", row: await ingestOrderPlaced(lake, raw) };
    case "OrderCancelled":
      return { kind: "OrderCancelled", row: await ingestOrderCancelled(lake, raw) };
    default:
      throw new ContractViolationError("event", [`type: expected OrderPlaced or OrderCancelled, got ${JSON.stringify(type)}`]);
  }
}
import { InvalidInvoiceStateError } from "./errors.js";
import type { OrderPlacedEvent } from "./orderPlacedEvent.js";

export type InvoiceStatus = "issued" | "paid";

export interface Invoice {
  readonly id: string;
  readonly orderId: string;
  readonly customerId: string;
  readonly customerEmail: string;
  /** Equal to the order total (`totalCents` of the event), integer minor units. */
  readonly amountCents: number;
  readonly currency: string;
  readonly status: InvoiceStatus;
  readonly issuedAt: string;
  readonly dueAt: string;
  /** Set once the invoice email has been delivered. */
  readonly emailedAt?: string;
  /** Set once an overdue reminder has been sent (at most one per invoice). */
  readonly reminderSentAt?: string;
  readonly paidAt?: string;
}

export const PAYMENT_TERMS_DAYS = 30;

const DAY_MS = 24 * 60 * 60 * 1000;

export function issueInvoice(event: OrderPlacedEvent, meta: { id: string; issuedAt: Date }): Invoice {
  return {
    id: meta.id,
    orderId: event.orderId,
    customerId: event.customerId,
    customerEmail: event.customerEmail,
    amountCents: event.totalCents,
    currency: event.currency,
    status: "issued",
    issuedAt: meta.issuedAt.toISOString(),
    dueAt: new Date(meta.issuedAt.getTime() + PAYMENT_TERMS_DAYS * DAY_MS).toISOString(),
  };
}

export function markEmailed(invoice: Invoice, at: Date): Invoice {
  return { ...invoice, emailedAt: at.toISOString() };
}

export function markReminded(invoice: Invoice, at: Date): Invoice {
  return { ...invoice, reminderSentAt: at.toISOString() };
}

/** Records the payment of an issued invoice. A paid invoice cannot be paid again. */
export function markPaid(invoice: Invoice, at: Date): Invoice {
  if (invoice.status !== "issued") {
    throw new InvalidInvoiceStateError(invoice.id, invoice.status, "paid");
  }
  return { ...invoice, status: "paid", paidAt: at.toISOString() };
}

/** An issued invoice is overdue once its due date has passed. */
export function isOverdue(invoice: Invoice, now: Date): boolean {
  return invoice.status === "issued" && Date.parse(invoice.dueAt) < now.getTime();
}
